/**
 * The one binding/scope analysis shared by the logical rewrites (standard optimizer pipeline, store-specific rewrites)
 * and the physical operators. Every rewrite obeys the same contract: a rewrite that needs a variable to carry the same
 * value at its new position as at its old one requires the variable to be <em>assured</em> there; <em>possible</em>
 * binding names may only block a rewrite, never permit it.
 * <p>
 * SPARQL evaluates most operands bottom-up: the bindings of an enclosing group are joined with an operand's result
 * afterwards, they are not visible while the operand is evaluated. RDF4J nevertheless evaluates several operators by
 * substituting an outer row into a nested tuple expression: the body of an {@code EXISTS} / {@code NOT EXISTS} (and of
 * the other {@link SubQueryValueOperator}s) sees the row its owning FILTER / OPTIONAL condition / BIND is evaluated on,
 * the right argument of a {@link Lateral} sees the left row, the right argument of a join may be evaluated with the
 * left row pushed in, and the whole query sees the request's incoming bindings.
 * <p>
 * The class answers three families of questions; where two consumers need a <em>different</em> answer to what looks
 * like the same question, both answers are kept under distinct names and the difference is documented on each:
 * <ul>
 * <li><b>Outer-visible names of a node</b> (parent-chain walks):
 * <ul>
 * <li>{@link #outerScope(QueryModelNode, Set)}: the full correlation-aware triple (executor-possible,
 * specification-possible, assured) for rewrites that decide whether a name is bound or unbound.</li>
 * <li>{@link #existsOrLateralOuterNames(QueryModelNode)}: only the names substituted by an enclosing EXISTS-style body
 * or LATERAL right argument, for rewrites that must not rename a substituted variable away.</li>
 * <li>{@link #lateralSubstitutedNames(QueryModelNode)}: only the names an enclosing LATERAL declares as substituted and
 * that intervening projections do not hide, for the executor.</li>
 * </ul>
 * </li>
 * <li><b>Scope boundaries</b>: {@link #isNestedSubSelectRoot(TupleExpr)}, {@link #isOutOfScopeForCorrelation},
 * {@link #isOutOfScopeForOptionalCorrelation}, {@link #receivesCorrelatedInput}, {@link #isPartOfSubQuery}.</li>
 * <li><b>Push rules</b>: {@link #canPushInto(Set, TupleExpr, TupleExpr)} and
 * {@link #filterDependsOnlyOnAssured(Filter, Set)}.</li>
 * </ul>
 * All predicates are conservative: when they cannot prove a rewrite sound they return {@code false} (or a superset of
 * visible names), which declines the rewrite but never changes results.
 */
@InternalUseOnly
public final class BindingScopeAnalysis {

	/**
	 * The outer-visible bindings of a node, computed by {@link BindingScopeAnalysis#outerScope(QueryModelNode, Set)}.
	 *
	 * @param possible        names the executor may hand to the node (superset of the two other sets)
	 * @param possibleInScope names SPARQL puts in scope at the node and that may be bound (superset of {@code assured})
	 * @param assured         names the enclosing context always binds
	 */
	public record OuterScope(Set<String> possible, Set<String> possibleInScope, Set<String> assured) {

		public static final OuterScope EMPTY = new OuterScope(Set.of(), Set.of(), Set.of());

		public OuterScope {
			possible = Collections.unmodifiableSet(new LinkedHashSet<>(Objects.requireNonNull(possible)));
			possibleInScope = Collections
					.unmodifiableSet(new LinkedHashSet<>(Objects.requireNonNull(possibleInScope)));
			assured = Collections.unmodifiableSet(new LinkedHashSet<>(Objects.requireNonNull(assured)));
		}

		public boolean isEmpty() {
			return possible.isEmpty();
		}
	}

	private BindingScopeAnalysis() {
	}

	// ---------------------------------------------------------------------------------------------------------------
	// Outer-visible names
	// ---------------------------------------------------------------------------------------------------------------

	/**
	 * Computes the outer-visible bindings of {@code node} by walking its parent chain at the time of the rewrite (so it
	 * stays correct across in-place tree rewrites). It returns three sets:
	 * <ul>
	 * <li>{@link OuterScope#possible()}: every name the executor may hand to the node, including names that reach it
	 * only through evaluation-order leaks the specification does not sanction (a sub-SELECT or MINUS right side
	 * evaluated with the outer row pushed in). A rewrite that assumes a name is <em>unbound</em> (an unbound OPTIONAL
	 * witness, a mandatory anchor on a right-only binding) must be blocked by this set.</li>
	 * <li>{@link OuterScope#possibleInScope()}: the subset of {@code possible} that SPARQL itself puts in scope at the
	 * node: the row substituted into an EXISTS / NOT EXISTS body, the left row of a LATERAL, the left row of an
	 * enclosing join and the request's incoming bindings. Across a sub-SELECT only the names it projects remain in
	 * scope, and only when an enclosing EXISTS body or LATERAL right argument substitutes them (the executor does so,
	 * see {@link #lateralSubstitutedNames(QueryModelNode)}); rows pushed in by a join, OPTIONAL or MINUS beyond a
	 * sub-SELECT stay executor-possible only. A rewrite that decides what the specification says about a name (such as
	 * folding {@code BOUND} of a name that is nowhere in scope to false) uses this set, so that a name the executor
	 * merely leaks across a sub-SELECT or MINUS boundary keeps its specification-correct treatment.</li>
	 * <li>{@link OuterScope#assured()}: names the enclosing context always binds when the node is evaluated. These may
	 * <em>enable</em> a rewrite (for example folding {@code BOUND} to true). The set is deliberately conservative: it
	 * is emptied at every boundary whose executor semantics do not guarantee the substitution (sub-SELECT projections,
	 * SERVICE, property paths, and the condition of a scope-changing FILTER outside a subquery, whose executor
	 * restricts the visible bindings to the filter's own group).</li>
	 * </ul>
	 * Compared with {@link #existsOrLateralOuterNames(QueryModelNode)} this walk also counts the rows an enclosing
	 * join, OPTIONAL or MINUS may push into its right argument, the names a LATERAL declares as substituted, and the
	 * request's incoming bindings, and it treats sub-SELECT projections as boundaries; see that method for why the
	 * narrower answer is kept.
	 *
	 * @param node                 the node whose enclosing evaluation context is analysed; its parent links must be
	 *                             intact
	 * @param incomingBindingNames the names bound by the request's incoming {@link BindingSet} (may be null)
	 * @return the names an enclosing context may or always binds when {@code node} is evaluated
	 */
	public static OuterScope outerScope(QueryModelNode node, Set<String> incomingBindingNames) {
		Objects.requireNonNull(node, "node must not be null");
		OuterScopeWalk walk = new OuterScopeWalk();
		// The condition of a scope-changing FILTER outside every subquery is evaluated against its own group's
		// bindings only (FilterIterator restricts the row to the filter's binding names), so outer names are never
		// assured for it.
		walk.assuredBlocked = node instanceof Filter filter && evaluatesConditionOnOwnGroupOnly(filter);

		QueryModelNode child = node;
		QueryModelNode parent = node.getParentNode();
		while (parent != null) {
			if (parent instanceof SubQueryValueOperator subQueryOperator && subQueryOperator.getSubQuery() == child) {
				// The subquery body is evaluated per outer row: climb through the value expression to the tuple
				// operator that evaluates the expression and contribute the row it evaluates it on.
				TupleExpr owner = expressionOwner(parent);
				if (owner == null) {
					break;
				}
				// The executor substitutes the owner row into the body (BindingAssignerOptimizer.substituteInScope),
				// including into the names every crossed sub-SELECT projects.
				walk.enterSubstitutionFrame();
				walk.contributeExpressionOwner(owner, childOnPathTo(owner, parent));
				child = owner;
				parent = owner.getParentNode();
				continue;
			}

			if (parent instanceof Lateral lateral) {
				if (lateral.getRightArg() == child) {
					// The right argument is evaluated once per left row; the model declares which of its bindings
					// flow in, and the executor substitutes them into the names every crossed sub-SELECT projects
					// (lateralSubstitutedNames).
					walk.enterSubstitutionFrame();
					TupleExpr left = lateral.getLeftArg();
					walk.addPossibleInScope(left.getBindingNames());
					walk.addPossibleInScope(lateral.getRightInputBindingNames());
					Set<String> leftAssured = new LinkedHashSet<>(left.getAssuredBindingNames());
					leftAssured.retainAll(lateral.getRightInputBindingNames());
					walk.addAssured(leftAssured);
				}
			} else if (parent instanceof Join || parent instanceof LeftJoin) {
				BinaryTupleOperator binary = (BinaryTupleOperator) parent;
				if (binary.getRightArg() == child) {
					// The right argument of a join is evaluated with the left row pushed in, and a FILTER relocated
					// into it by an earlier optimizer legitimately sees that row; the left row is only possibly
					// present (the executor may also evaluate the right side on its own), so it may only block.
					walk.addPossibleInScope(binary.getLeftArg().getBindingNames());
				}
			} else if (parent instanceof Difference difference) {
				if (difference.getRightArg() == child) {
					// MINUS evaluates its right side independently by specification, but the executor may push the
					// left row in; the left names are executor-possible only.
					walk.addPossibleLeaked(difference.getLeftArg().getBindingNames());
				}
			} else if (isNonRootProjection(parent)) {
				// A sub-SELECT starts a fresh scope by specification: rows a join, OPTIONAL or MINUS further out
				// pushes in stay executor-possible but are neither in scope nor assured. An enclosing EXISTS body or
				// LATERAL right argument does substitute its row into the names the sub-SELECT projects, so those
				// names come back into scope at such a frame (see enterSubstitutionFrame).
				walk.crossSubSelect(projectedSourceNames(parent));
			} else if (isAssuranceBoundary(parent)) {
				walk.assuredBlocked = true;
			}

			child = parent;
			parent = parent.getParentNode();
		}

		if (incomingBindingNames != null && !incomingBindingNames.isEmpty()) {
			// The request's incoming bindings apply to the whole query, sub-SELECTs included.
			walk.possible.addAll(incomingBindingNames);
			walk.possibleInScope.addAll(incomingBindingNames);
			walk.addAssured(incomingBindingNames);
		}
		return walk.result();
	}

	/**
	 * Names that may be bound at {@code node} by the two SPARQL <em>substitution</em> scopes that the node's own
	 * subtree does not show: the solution substituted into an enclosing EXISTS/NOT EXISTS body (all names visible to
	 * the tuple operator whose value expression contains the subquery) and the left-hand bindings fed into the right
	 * argument of an enclosing {@link Lateral}. The result is a conservative superset of those names; an empty set
	 * means {@code node} is not inside such a scope.
	 * <p>
	 * This deliberately differs from {@link #outerScope(QueryModelNode, Set)}{@code .possible()}, which is kept
	 * separate rather than substituted here because the two answers are not equal:
	 * <ul>
	 * <li>it does not count the left row an enclosing join / OPTIONAL / MINUS may push into its right argument, nor the
	 * request's incoming bindings: its consumer ({@code SameTermFilterOptimizer}) must keep treating a variable that
	 * only such a push could bind as unbound in its own group, exactly as before;</li>
	 * <li>for a LATERAL it uses the left argument's binding names, not the declared right-input names;</li>
	 * <li>for an expression owner other than a FILTER it also adds the owner's operand names (for example the input of
	 * a GROUP, whose own binding names are only the group keys and aggregates);</li>
	 * <li>it does not stop at sub-SELECT boundaries.</li>
	 * </ul>
	 * Only filter <em>arguments</em> contribute for a FILTER owner: {@link Filter#getBindingNames()} would also add the
	 * EXISTS sub-query's own names, which are not visible from outside and would wrongly mark body-only variables as
	 * correlated.
	 *
	 * @param node the node whose enclosing scopes are inspected
	 * @return the possibly bound names contributed by enclosing substitution scopes
	 */
	public static Set<String> existsOrLateralOuterNames(QueryModelNode node) {
		Set<String> visible = null;
		QueryModelNode child = node;
		QueryModelNode parent = node.getParentNode();
		while (parent != null) {
			if (parent instanceof SubQueryValueOperator) {
				TupleExpr owner = expressionOwner(parent);
				if (owner != null) {
					visible = addAll(visible, expressionRowNames(owner));
					if (!(owner instanceof Filter)) {
						if (owner instanceof UnaryTupleOperator unary) {
							visible = addAll(visible, unary.getArg().getBindingNames());
						} else if (owner instanceof BinaryTupleOperator binary) {
							visible = addAll(visible, binary.getLeftArg().getBindingNames());
							visible = addAll(visible, binary.getRightArg().getBindingNames());
						}
					}
				}
			} else if (parent instanceof Lateral lateral && child == lateral.getRightArg()) {
				visible = addAll(visible, lateral.getLeftArg().getBindingNames());
			}
			child = parent;
			parent = parent.getParentNode();
		}
		return visible == null ? Set.of() : visible;
	}

	/**
	 * The binding names that enclosing {@link Lateral} operators substitute into {@code node}. Under LATERAL semantics
	 * the right-hand side is evaluated once per left row with the left row's bindings substituted, so inside it those
	 * names are constants and never fresh variables: they must not be treated as badly-designed problem variables, and
	 * a MINUS or sub-select inside the right-hand side may be evaluated with them bound. Names that an intervening
	 * projection does not project (as a source name) are hidden by it and are therefore excluded.
	 * <p>
	 * The set is static: it is every name the LATERAL declares as substituted, while at runtime only the names bound in
	 * the current left row are actually substituted. The two agree whenever the incoming binding of a declared name
	 * comes from the LATERAL's left row. They diverge only when an operator enclosing the whole LATERAL correlates a
	 * declared name that the left row leaves unbound; that push is the enclosing operator's responsibility (see
	 * {@link #isOutOfScopeForCorrelation}), and a per-row set would have to be threaded through every operator, so the
	 * static answer is used here.
	 * <p>
	 * Unlike the LATERAL frame of {@link #outerScope(QueryModelNode, Set)} (which keeps hidden names as
	 * executor-possible leaks and also adds the left argument's names), this executor view returns only the declared
	 * names that are genuinely substituted, because its consumers treat them as constants.
	 *
	 * @param node a node with an intact parent chain; a parentless node yields the empty set.
	 * @return the substituted names in scope at {@code node}, possibly empty, never {@code null}.
	 */
	public static Set<String> lateralSubstitutedNames(QueryModelNode node) {
		Set<String> substituted = null;
		Set<String> visible = null;
		QueryModelNode current = node;
		for (QueryModelNode parent = node.getParentNode(); parent != null; parent = parent.getParentNode()) {
			if (parent instanceof Lateral lateral) {
				if (lateral.getRightArg() == current) {
					for (String name : lateral.getRightInputBindingNames()) {
						if (visible == null || visible.contains(name)) {
							if (substituted == null) {
								substituted = new LinkedHashSet<>();
							}
							substituted.add(name);
						}
					}
				}
			} else if (parent instanceof Projection projection) {
				visible = retainVisible(visible, sourceNames(projection.getProjectionElemList()));
			} else if (parent instanceof MultiProjection multiProjection) {
				Set<String> names = new HashSet<>();
				for (ProjectionElemList projection : multiProjection.getProjections()) {
					names.addAll(sourceNames(projection));
				}
				visible = retainVisible(visible, names);
			}
			current = parent;
		}
		return substituted == null ? Collections.emptySet() : substituted;
	}

	// ---------------------------------------------------------------------------------------------------------------
	// Scope boundaries
	// ---------------------------------------------------------------------------------------------------------------

	/**
	 * Whether evaluating {@code expr} with the bindings of a sibling operand would change its result compared to
	 * bottom-up evaluation: a variable scope change, a sub-select, or a MINUS in the current scope all make the pushed
	 * bindings selections on variables that are fresh inside {@code expr}.
	 */
	public static boolean isOutOfScopeForCorrelation(TupleExpr expr) {
		return TupleExprs.isVariableScopeChange(expr) || isOutOfScopeForOptionalCorrelation(expr);
	}

	/**
	 * Whether the optional part of an OPTIONAL must be evaluated independently of the left rows: a sub-select or a
	 * MINUS inside it is a bottom-up scope boundary for which a pushed left row is a selection on fresh variables. A
	 * bare variable scope change (the parser flags every {@code { A } UNION { B }}) is deliberately not included: it
	 * governs BIND/FILTER visibility, not correlation, and the OPTIONAL's bounded correlated and adaptive
	 * implementations stay sound for it.
	 */
	public static boolean isOutOfScopeForOptionalCorrelation(TupleExpr optionalPart) {
		return TupleExprs.containsSubquery(optionalPart) || containsDifferenceInCurrentScope(optionalPart);
	}

	/**
	 * Whether {@code expr} contains a {@link Difference} that is evaluated in the current scope, i.e. not hidden behind
	 * a {@link Service} or a {@link Lateral} (whose right-hand side has its own substitution scope).
	 */
	static boolean containsDifferenceInCurrentScope(TupleExpr expr) {
		if (expr instanceof Difference) {
			return true;
		}
		if (expr instanceof Service || expr instanceof Lateral) {
			return false;
		}
		for (TupleExpr child : TupleExprs.getChildren(expr)) {
			if (containsDifferenceInCurrentScope(child)) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether {@code node} can be evaluated with bindings that a correlating operator pushed down, as opposed to only
	 * the query's external bindings. RDF4J treats external bindings as constants in the whole query, so they may flow
	 * into every operand; correlated bindings are the rows of a sibling operand and are only in scope where SPARQL says
	 * so. A node is in a correlated position when it is (inside) the right-hand side of a {@link Join},
	 * {@link LeftJoin}, {@link Lateral} or {@link Difference}. An {@link Exists} body substitutes the probe row into
	 * the whole body, so the walk stops there: inside EXISTS every incoming binding is a constant.
	 *
	 * @param node a node with an intact parent chain; a parentless node is a top-level operand.
	 */
	public static boolean receivesCorrelatedInput(QueryModelNode node) {
		QueryModelNode current = node;
		for (QueryModelNode parent = node.getParentNode(); parent != null; parent = parent.getParentNode()) {
			if (parent instanceof Exists) {
				return false;
			}
			if ((parent instanceof Join || parent instanceof LeftJoin || parent instanceof Lateral
					|| parent instanceof Difference) && ((BinaryTupleOperator) parent).getRightArg() == current) {
				return true;
			}
			current = parent;
		}
		return false;
	}

	/**
	 * Whether {@code node} is the root of a nested sub-select unit: the sub-select's {@link Projection} together with
	 * the DISTINCT/REDUCED/ORDER/LIMIT operators the parser stacks above it, with {@code node} being the topmost of
	 * them, and the unit sitting inside some other operator rather than at the top of the query. Such a unit is a
	 * bottom-up scope boundary: the bindings a correlating operator pushes into it are not in scope inside it, and its
	 * projected names are joined with those bindings by compatibility only after the whole unit (including its LIMIT)
	 * has been evaluated. A top-level unit (below nothing but {@link QueryRoot}, {@link DescribeOperator} or the
	 * planner's {@link MaterializeTupleExpr}) keeps receiving the query's external bindings, which RDF4J treats as
	 * constants in the whole query.
	 * <p>
	 * This executor predicate is kept separate from the sub-SELECT frame of {@link #outerScope(QueryModelNode, Set)}
	 * ({@link #isNonRootProjection(QueryModelNode)}) because they differ on purpose: this one honours
	 * {@link Projection#isSubquery()}, ignores {@link MultiProjection}, identifies the unit root (not every projection)
	 * and treats the planner's {@link MaterializeTupleExpr} wrapper as top level, since it runs on planned trees; the
	 * rewrite-time frame is structural only (the parser leaves {@code isSubquery()} true on the outermost SELECT too)
	 * and runs before the planner wraps anything.
	 *
	 * @param node a node with an intact parent chain; a parentless unit is a top-level unit.
	 */
	public static boolean isNestedSubSelectRoot(TupleExpr node) {
		if (!isSubSelectUnit(node)) {
			return false;
		}
		QueryModelNode parent = node.getParentNode();
		if (isSubSelectUnitWrapper(parent)) {
			// not the topmost operator of the unit
			return false;
		}
		for (QueryModelNode ancestor = parent; ancestor != null; ancestor = ancestor.getParentNode()) {
			if (!(isQueryTopOperator(ancestor) || ancestor instanceof MaterializeTupleExpr)) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether {@code node} lies inside a {@link SubQueryValueOperator} (an EXISTS-style body or its value expression),
	 * where the executor evaluates it with the substituted outer row rather than restricted to its own group.
	 *
	 * @param node a node with an intact parent chain (the node itself is included in the check)
	 */
	public static boolean isPartOfSubQuery(QueryModelNode node) {
		QueryModelNode current = node;
		while (current != null) {
			if (current instanceof SubQueryValueOperator) {
				return true;
			}
			current = current.getParentNode();
		}
		return false;
	}

	// ---------------------------------------------------------------------------------------------------------------
	// Push rules
	// ---------------------------------------------------------------------------------------------------------------

	/**
	 * Whether a predicate over {@code variables} that currently sits above a binary operator may be evaluated inside
	 * {@code target}, one operand of that operator, before the operator merges it with {@code sibling}.
	 * <p>
	 * Sound because the predicate outcome depends only on {@code variables}: for each variable either {@code target}
	 * assures it (join compatibility forces the merged value to equal the target row's value) or {@code sibling} can
	 * never bind it (the merged value is the target row's value, possibly unbound in both). A variable that is only
	 * possibly bound by {@code target} and also bindable by {@code sibling} must stay above the operator: a target row
	 * that leaves it unbound may still receive it from the sibling, and a target row that binds it may still be dropped
	 * or extended differently after the merge.
	 * <p>
	 * {@link Filter#getBindingNames()} over-approximates (it adds the EXISTS sub-query's names when the condition is
	 * directly an {@code Exists}); possible names are consumed here only as a blocker, so the over-approximation can
	 * only decline a push.
	 *
	 * @param variables the variables the predicate observes
	 * @param target    the operand the predicate would move into
	 * @param sibling   the other operand of the same binary operator
	 * @return {@code true} when the predicate may move into {@code target}
	 */
	public static boolean canPushInto(Set<String> variables, TupleExpr target, TupleExpr sibling) {
		if (!target.getBindingNames().containsAll(variables)) {
			return false;
		}
		if (variables.isEmpty()) {
			return true;
		}
		Set<String> assured = target.getAssuredBindingNames();
		if (assured.containsAll(variables)) {
			return true;
		}
		Set<String> siblingPossible = sibling.getBindingNames();
		for (String variable : variables) {
			if (!assured.contains(variable) && siblingPossible.contains(variable)) {
				return false;
			}
		}
		return true;
	}

	/**
	 * Whether every variable in {@code names} that {@code filter}'s condition mentions (including inside EXISTS bodies)
	 * is assured by the filter's argument. When this holds, evaluating the filter with those names pre-bound from an
	 * outer, join-compatible row yields the same outcome as evaluating it unbound and joining afterwards.
	 *
	 * @param filter the filter whose evaluation context is about to gain bindings for {@code names}
	 * @param names  the names that may become bound before the filter is evaluated
	 * @return {@code true} when the filter cannot observe whether {@code names} are pre-bound
	 */
	public static boolean filterDependsOnlyOnAssured(Filter filter, Set<String> names) {
		if (names.isEmpty()) {
			return true;
		}
		Set<String> conditionNames = new HashSet<>(VarNameCollector.process(filter.getCondition()));
		conditionNames.retainAll(names);
		if (conditionNames.isEmpty()) {
			return true;
		}
		return filter.getArg().getAssuredBindingNames().containsAll(conditionNames);
	}

	// ---------------------------------------------------------------------------------------------------------------
	// Runtime helper
	// ---------------------------------------------------------------------------------------------------------------

	/**
	 * Restricts {@code bindings} to the supplied names. The input instance is returned when nothing has to be removed.
	 */
	public static BindingSet retain(BindingSet bindings, Set<String> names) {
		if (bindings.isEmpty()) {
			return bindings;
		}
		if (names.isEmpty()) {
			return EmptyBindingSet.getInstance();
		}
		boolean complete = true;
		for (String name : bindings.getBindingNames()) {
			if (!names.contains(name)) {
				complete = false;
				break;
			}
		}
		if (complete) {
			return bindings;
		}
		QueryBindingSet retained = new QueryBindingSet(names.size());
		for (String name : names) {
			if (bindings.hasBinding(name)) {
				retained.addBinding(bindings.getBinding(name));
			}
		}
		return retained.isEmpty() ? EmptyBindingSet.getInstance() : retained;
	}

	// ---------------------------------------------------------------------------------------------------------------
	// Shared private predicates
	// ---------------------------------------------------------------------------------------------------------------

	/** Mutable state of one {@link #outerScope(QueryModelNode, Set)} parent-chain walk. */
	private static final class OuterScopeWalk {
		final Set<String> possible = new LinkedHashSet<>();
		final Set<String> possibleInScope = new LinkedHashSet<>();
		final Set<String> assured = new LinkedHashSet<>();
		/**
		 * True once a sub-SELECT boundary has been crossed and no substitution frame has been entered since: names from
		 * frames further out only leak in.
		 */
		boolean leakOnly;
		/**
		 * The names every crossed sub-SELECT projects (as source names), i.e. the only names a substitution frame
		 * beyond those boundaries can put in scope; {@code null} while no sub-SELECT boundary has been crossed.
		 */
		Set<String> substitutable;
		/** True once a boundary has been crossed beyond which no outer name is guaranteed to be substituted. */
		boolean assuredBlocked;

		void crossSubSelect(Set<String> projectedNames) {
			substitutable = retainVisible(substitutable, projectedNames);
			leakOnly = true;
			assuredBlocked = true;
		}

		/**
		 * Enters an EXISTS-style or LATERAL frame: its row, and the rows of frames further out that reach it, are
		 * substituted into the node, restricted to {@link #substitutable}. Assurance stays blocked across a crossed
		 * sub-SELECT (conservative: an in-scope name may only block a fold to false, never enable a fold to true).
		 */
		void enterSubstitutionFrame() {
			leakOnly = false;
		}

		void addPossibleInScope(Set<String> names) {
			possible.addAll(names);
			if (leakOnly) {
				return;
			}
			if (substitutable == null) {
				possibleInScope.addAll(names);
				return;
			}
			for (String name : names) {
				if (substitutable.contains(name)) {
					possibleInScope.add(name);
				}
			}
		}

		void addPossibleLeaked(Set<String> names) {
			possible.addAll(names);
		}

		void addAssured(Set<String> names) {
			if (!assuredBlocked) {
				assured.addAll(names);
			}
		}

		/** Contributes the row an expression-owning tuple operator evaluates its expression on. */
		void contributeExpressionOwner(TupleExpr owner, QueryModelNode ownerChild) {
			if (owner instanceof Filter filter && filter.getCondition() == ownerChild) {
				addPossibleInScope(expressionRowNames(filter));
				addAssured(filter.getArg().getAssuredBindingNames());
				// Outside a subquery a scope-changing FILTER evaluates its condition on its own group's bindings
				// only.
				if (evaluatesConditionOnOwnGroupOnly(filter)) {
					assuredBlocked = true;
				}
				return;
			}
			if (owner instanceof LeftJoin leftJoin && leftJoin.getCondition() == ownerChild) {
				// The OPTIONAL condition is evaluated on the joined row of both arguments.
				addPossibleInScope(expressionRowNames(leftJoin));
				addAssured(leftJoin.getLeftArg().getAssuredBindingNames());
				addAssured(leftJoin.getRightArg().getAssuredBindingNames());
				return;
			}
			if (owner instanceof Extension extension) {
				// BIND expressions see the argument row (and, conservatively, earlier extension elements).
				addPossibleInScope(expressionRowNames(extension));
				addAssured(extension.getArg().getAssuredBindingNames());
				return;
			}
			// Any other owner (ORDER BY, GROUP BY aggregates, ...): its rows are possible, nothing is assured.
			addPossibleInScope(owner.getBindingNames());
			assuredBlocked = true;
		}

		OuterScope result() {
			if (possible.isEmpty()) {
				return OuterScope.EMPTY;
			}
			return new OuterScope(possible, possibleInScope, assured);
		}
	}

	/**
	 * The tuple operator whose value expression contains {@code valueNode}: the nearest {@link TupleExpr} ancestor, or
	 * {@code null} when the value expression is detached.
	 */
	private static TupleExpr expressionOwner(QueryModelNode valueNode) {
		QueryModelNode current = valueNode.getParentNode();
		while (current != null && !(current instanceof TupleExpr)) {
			current = current.getParentNode();
		}
		return (TupleExpr) current;
	}

	/** The child of {@code ancestor} on the parent chain of {@code descendant}. */
	private static QueryModelNode childOnPathTo(QueryModelNode ancestor, QueryModelNode descendant) {
		QueryModelNode child = descendant;
		while (child.getParentNode() != ancestor) {
			child = child.getParentNode();
		}
		return child;
	}

	/**
	 * The names of the row an expression-owning tuple operator evaluates its value expressions on. For a FILTER that is
	 * its argument's names: {@link Filter#getBindingNames()} would also add an EXISTS sub-query's own names, which are
	 * not visible from outside. Every other owner (OPTIONAL condition, BIND, ORDER BY, ...) evaluates on its own
	 * binding names.
	 */
	private static Set<String> expressionRowNames(TupleExpr owner) {
		if (owner instanceof Filter filter) {
			return filter.getArg().getBindingNames();
		}
		return owner.getBindingNames();
	}

	/**
	 * Whether the executor evaluates {@code filter}'s condition against the filter's own group only: a scope-changing
	 * FILTER outside every subquery (FilterIterator restricts the row to the filter's binding names).
	 */
	private static boolean evaluatesConditionOnOwnGroupOnly(Filter filter) {
		return filter.isVariableScopeChange() && !isPartOfSubQuery(filter);
	}

	/**
	 * The rewrite-time sub-SELECT frame of {@link #outerScope(QueryModelNode, Set)}: every {@link MultiProjection} and
	 * every {@link Projection} that is not the outermost SELECT. The decision is structural:
	 * {@link Projection#isSubquery()} defaults to true and the parser leaves it so for the outermost SELECT as well,
	 * whose argument does see the request's incoming bindings. See {@link #isNestedSubSelectRoot(TupleExpr)} for the
	 * executor's differing notion.
	 */
	private static boolean isNonRootProjection(QueryModelNode parent) {
		if (parent instanceof Projection projection) {
			return !isRootProjection(projection);
		}
		return parent instanceof MultiProjection;
	}

	/** The source names a sub-SELECT frame accepted by {@link #isNonRootProjection(QueryModelNode)} projects. */
	private static Set<String> projectedSourceNames(QueryModelNode projectionNode) {
		if (projectionNode instanceof Projection projection) {
			return sourceNames(projection.getProjectionElemList());
		}
		Set<String> names = new HashSet<>();
		for (ProjectionElemList projection : ((MultiProjection) projectionNode).getProjections()) {
			names.addAll(sourceNames(projection));
		}
		return names;
	}

	private static boolean isAssuranceBoundary(QueryModelNode parent) {
		return parent instanceof Service
				|| parent instanceof ArbitraryLengthPath
				|| parent instanceof ZeroLengthPath;
	}

	/** Whether every ancestor of {@code projection} is a query-top operator or a sub-select unit wrapper. */
	private static boolean isRootProjection(Projection projection) {
		QueryModelNode ancestor = projection.getParentNode();
		while (ancestor != null) {
			if (!(isQueryTopOperator(ancestor) || isSubSelectUnitWrapper(ancestor))) {
				return false;
			}
			ancestor = ancestor.getParentNode();
		}
		return true;
	}

	/** The operators that sit above the outermost query without starting a nested scope. */
	private static boolean isQueryTopOperator(QueryModelNode node) {
		return node instanceof QueryRoot || node instanceof DescribeOperator;
	}

	private static boolean isSubSelectUnit(TupleExpr node) {
		TupleExpr current = node;
		while (isSubSelectUnitWrapper(current)) {
			current = ((UnaryTupleOperator) current).getArg();
		}
		return current instanceof Projection projection && projection.isSubquery();
	}

	/** The solution modifiers the parser stacks above a SELECT's projection. */
	private static boolean isSubSelectUnitWrapper(QueryModelNode node) {
		return node instanceof Slice || node instanceof Distinct || node instanceof Reduced || node instanceof Order;
	}

	private static Set<String> sourceNames(ProjectionElemList projection) {
		List<ProjectionElem> elements = projection.getElements();
		Set<String> names = new HashSet<>(elements.size());
		for (ProjectionElem element : elements) {
			names.add(element.getName());
		}
		return names;
	}

	private static Set<String> retainVisible(Set<String> visible, Set<String> names) {
		if (visible == null) {
			return names;
		}
		Set<String> retained = new HashSet<>(visible);
		retained.retainAll(names);
		return retained;
	}

	private static Set<String> addAll(Set<String> target, Set<String> names) {
		if (names.isEmpty()) {
			return target;
		}
		if (target == null) {
			target = new HashSet<>();
		}
		target.addAll(names);
		return target;
	}
}
